// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/utils/Counters.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";


contract SmartContract is ERC721, Ownable {
    using Counters for Counters.Counter;
    using Strings for uint256;
    uint256 list = 0;
    Counters.Counter _tokenIds;
    mapping(uint256 => string) _tokenURIs;

    struct RenderToken {
        uint256 id;
        string uri;
    }

    struct RenderPrice {
        uint256 id;
        uint256 price;
    }

    event NftBought(address _seller, address _buyer, uint256 _price);
    event TokenListed(uint256 _tokenId, uint256 _price);


    mapping(uint256 => uint256) public tokenIdToPrice;


    constructor() ERC721("Smart Contract", "SC"){}

    function _setTokenURI(uint256 tokenId, string memory _tokenURI) internal {
        _tokenURIs[tokenId] = _tokenURI;
    }

    function tokenURI(uint256 tokenId)
        public
        view
        virtual
        override
        returns (string memory)
    {
        require(_exists(tokenId));
        string memory _tokenURI = _tokenURIs[tokenId];
        return _tokenURI;
    }

    function getAllTokens() public view returns (RenderToken[] memory) {
        uint256 latestId = _tokenIds.current();
        uint256 counter = 0;
        RenderToken[] memory res = new RenderToken[](list);
        for (uint256 i = 0; i < latestId; i++) {
            if (_exists(i)) {
                string memory uri = tokenURI(i);
                if (tokenIdToPrice[i] > 0) {
                    res[counter] = RenderToken(i, uri);
                    counter++;
                }
            }
        }
        return res;
    }

    function getPriceList() public view returns (RenderPrice[] memory) {
        uint256 latestId = _tokenIds.current();   

        RenderPrice[] memory res = new RenderPrice[](latestId);
        for (uint256 i = 0; i < latestId; i++) {
            uint256 price = 0;
            if (_exists(i)) { 
                if(tokenIdToPrice[i] != 0){
                   price = tokenIdToPrice[i];
                }
                res[i] = RenderPrice(i, price); 

            }
        }
        return res;

    } 

    function getMyTokens(address _owner)
        public
        view
        returns (RenderToken[] memory)
    {
        uint256 latestId = _tokenIds.current();
        uint256 tokenCount = balanceOf(_owner);
        RenderToken[] memory result = new RenderToken[](tokenCount);

        uint256 resultIndex = 0;

        for (uint256 i = 0; i < latestId; i++) {
            if (_exists(i)) {
                string memory uri = tokenURI(i);
                if (ownerOf(i) == _owner) {
                    result[resultIndex] = RenderToken(i, uri);
                    resultIndex++;
                }
            }
        }
        return result;
    }

    function mint(address recipient, string memory uri)
        public
        returns (uint256)
    {
        uint256 newId = _tokenIds.current();
        _mint(recipient, newId);
        _setTokenURI(newId, uri);
        _tokenIds.increment(); 
        return newId;
    }


    function allowBuy(uint256 _tokenId, uint256 _price) public {
        require(msg.sender == ownerOf(_tokenId), "Not owner of this token");
        require(_price > 0, "Price zero");
        tokenIdToPrice[_tokenId] = _price;
        if(_tokenId<list){
        }else{
            list++;
        }

        emit TokenListed(_tokenId, _price);
        setApprovalForAll(address(this), true);

    }

    function disallowBuy(uint256 _tokenId) public {
        require(msg.sender == ownerOf(_tokenId), "Not owner of this token");
        tokenIdToPrice[_tokenId] = 0;

    }


    function buy(uint256 _tokenId) public payable {
        uint256 price = tokenIdToPrice[_tokenId];
        require(price > 0, 'This token is not for sale');
        //require(msg.value == price, 'Incorrect value');
        address seller = ownerOf(_tokenId);

        // IERC20 tokenContract = IERC20(address(this));
